#include "wirelength_register.hpp"

#include <map>
#include <stdexcept>

#include "attrs.hpp"
#include "node_util.hpp"
#include "pass/partition/flatten.hpp"
#include "register_replica.hpp"
namespace livehd::placement {
bool wire_register_has_reset(hhds::Node_class node, const liberty::Dff_cell& cell) {
  // A Liberty reset pin can be tied inactive or generated by arbitrary logic.
  // Fold only after assertion of a single, externally driven reset.
  if (cell.latch || cell.reset0_pin.empty() == cell.reset1_pin.empty()) {
    return false;
  }
  auto reset = node.get_sink_pin(cell.reset0_pin.empty() ? cell.reset1_pin : cell.reset0_pin);
  if (reset.is_invalid() || reset.get_driver_pins().size() != 1) {
    return false;
  }
  auto input = reset.get_driver_pin();
  return !input.is_const() && graph_util::is_graph_input_pin(input);
}
bool has_wire_register_replicas(hhds::Graph& graph) {
  if (!graph.has_attr(attrs::aggregate_origin)) {
    return false;
  }
  for (auto n : graph.body().nodes()) {
    if (graph_util::is_placed_replica(n)) {
      return true;
    }
  }
  return false;
}
std::shared_ptr<hhds::Graph> wire_register_proof_view(hhds::Graph& graph, hhds::GraphLibrary& owner,
                                                      const liberty::Cell_library& technology, bool after_reset) {
  if (!has_wire_register_replicas(graph)) {
    return {};
  }
  auto proof = partition::flatten_hierarchy(&graph, &owner, graph.get_name(), nullptr, false, {}, {}, true);
  if (!proof) {
    throw std::runtime_error("cannot open placed register proof view");
  }
  std::map<std::string, liberty::Dff_cell> sequential;
  for (const auto& dff : technology.dffs) {
    sequential.emplace(dff.name, dff);
  }
  for (const auto& dff : technology.async_dffs) {
    sequential.emplace(dff.name, dff);
  }
  const auto                    sources = graph_util::placed_replica_sources(*proof);
  unsigned                      folded  = 0;
  std::vector<hhds::Node_class> copies;
  for (auto n : proof->body().nodes()) {
    if (sources.contains(n.get_debug_nid())) {
      copies.push_back(n);
    }
  }
  for (auto copy : copies) {
    auto       original = sources.at(copy.get_debug_nid());
    const auto io       = copy.get_subnode_io();
    if (!io) {
      continue;
    }
    const auto characterized = sequential.find(std::string(io->get_name()));
    if (characterized == sequential.end() || characterized->second.n_out != 1 || io->get_output_pin_decls().size() != 1) {
      continue;
    }
    const auto& dff = characterized->second;
    if (!after_reset || !wire_register_has_reset(original, dff)) {
      continue;
    }
    auto old = copy.get_driver_pin(dff.q_pin), same = original.get_driver_pin(dff.q_pin);
    if (old.is_invalid() || same.is_invalid()) {
      continue;
    }
    // Equal reset/initial state and identical transition relation establish
    // Qcopy == Qoriginal by induction for every subsequent clock edge.
    auto loads = graph_util::Edge_vec(old.out_edges().begin(), old.out_edges().end());
    for (auto e : loads) {
      e.sink.del_sink(old);
      e.sink.connect_driver(same);
    }
    copy.del_node();
    ++folded;
  }
  return folded ? proof : nullptr;
}
}  // namespace livehd::placement
